def compute(vars):
    value = vars["v1"] - vars["v2"]
    return {
        "value": value,
        "trace": {
            "v1": vars["v1"],
            "v2": vars["v2"],
            "difference": value,
            "output_meta": {
                "currency": "USD",
                "scale": "millions",
                "unit": None
            }
        }
    }
